import{_ as a,c as n,o as r,ai as t}from"./chunks/framework.D76OLbos.js";const u=JSON.parse('{"title":"Container Days Hamburg","description":"","frontmatter":{"title":"Container Days Hamburg","date":"2026-09-02","banner":"assets/events/20260902_container_days_hamburg_banner.svg","bannerMobile":"assets/events/20260902_container_days_hamburg_banner_mobile.svg","bannerSmall":"assets/events/20260902_container_days_hamburg_banner_small.svg","backgroundhex":"#889aa4ff","tags":["neonephos","container-days"],"rssPubDate":"2026-08-10","published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_09_02_Container_Days_Hamburg.md","filePath":"events/2026_09_02_Container_Days_Hamburg.md"}'),o={name:"events/2026_09_02_Container_Days_Hamburg.md"};function s(i,e,l,p,d,c){return r(),n("div",null,e[0]||(e[0]=[t('<h2 id="containerdays-conference-2026" tabindex="-1">ContainerDays Conference 2026 <a class="header-anchor" href="#containerdays-conference-2026" aria-label="Permalink to &quot;ContainerDays Conference 2026&quot;">​</a></h2><p><strong>ContainerDays Conference</strong> returns to Hamburg from <strong>September 8-10, 2026</strong>, bringing together the cloud-native community for three days of learning, networking, and technical exchange.</p><p>The conference focuses on <strong>Kubernetes, Containers, DevOps, Cloud Native, and Platform Engineering</strong>, featuring hands-on sessions, technical talks, and discussions with industry experts and practitioners.</p><p>This year&#39;s event features several contributions from members of the NeoNephos ecosystem:</p><h3 id="september-2" tabindex="-1">September 2 <a class="header-anchor" href="#september-2" aria-label="Permalink to &quot;September 2&quot;">​</a></h3><h3 id="sovereign-by-design-open-by-default" tabindex="-1">Sovereign by Design, Open by Default <a class="header-anchor" href="#sovereign-by-design-open-by-default" aria-label="Permalink to &quot;Sovereign by Design, Open by Default&quot;">​</a></h3><p><strong>Christian Hüning</strong> and <strong>Niklas Voss</strong></p><p>🕘 9:45 am - 10:20 am</p><p>📍 Main Track - Room 2</p><p>This session explores how sovereignty and openness can reinforce one another rather than being treated as opposing goals. Drawing on experiences from NeoNephos and sovereign cloud initiatives, the speakers will discuss resilience, supply-chain trust, interoperability, and open collaboration.</p><h3 id="building-agentic-ready-infrastructure-with-kcp-workspaces-and-api-export" tabindex="-1">Building Agentic-Ready Infrastructure with kcp Workspaces and API Export <a class="header-anchor" href="#building-agentic-ready-infrastructure-with-kcp-workspaces-and-api-export" aria-label="Permalink to &quot;Building Agentic-Ready Infrastructure with kcp Workspaces and API Export&quot;">​</a></h3><p><strong>Abubakar Siddiq Ango</strong></p><p>🕥 10:30 am - 11:05 am</p><p>📍 Platform Engineering Track - Room 1</p><p>NeoNephos Ambassador Abubakar Siddiq Ango will share insights from his experience in the cloud-native community and discuss the role of open collaboration in shaping the future of cloud-native ecosystems.</p><h3 id="september-3" tabindex="-1">September 3 <a class="header-anchor" href="#september-3" aria-label="Permalink to &quot;September 3&quot;">​</a></h3><h3 id="building-a-sovereign-vendor-agnostic-cloud-api" tabindex="-1">Building a Sovereign, Vendor-Agnostic Cloud API <a class="header-anchor" href="#building-a-sovereign-vendor-agnostic-cloud-api" aria-label="Permalink to &quot;Building a Sovereign, Vendor-Agnostic Cloud API&quot;">​</a></h3><p><strong>Cyrill Berg</strong> and <strong>Kevin Stellmacher</strong></p><p>🕚 11:20 am - 11:55 am</p><p>📍 Main Track - Room 1</p><p>This talk presents an approach to building portable and provider-agnostic cloud APIs based on open standards, Kubernetes-native technologies, kcp, and Platform Mesh. The session demonstrates how sovereign cloud services can remain interoperable across different infrastructures.</p><h3 id="september-4" tabindex="-1">September 4 <a class="header-anchor" href="#september-4" aria-label="Permalink to &quot;September 4&quot;">​</a></h3><h3 id="one-platform-could-not-fit-them-all" tabindex="-1">One Platform Could Not Fit Them All <a class="header-anchor" href="#one-platform-could-not-fit-them-all" aria-label="Permalink to &quot;One Platform Could Not Fit Them All&quot;">​</a></h3><p><strong>Artem Lajko</strong> and <strong>Annika Opitz</strong></p><p>🕙 10:15 am - 10:50 am</p><p>📍 Platform Engineering Track - Room 2</p><p>Drawing from real-world experience, the speakers share lessons learned from building an open-source platform framework that balances standardization and autonomy across multiple platform teams and large-scale environments.</p><p><strong>Whether you&#39;re a developer, platform engineer, infrastructure operator, or open-source contributor, ContainerDays offers an opportunity to connect with the community and explore the latest developments across the cloud-native ecosystem.</strong></p><p>🔗 Learn more and register: <a href="https://www.containerdays.io/containerdays-hamburg-2026/" target="_blank" rel="noreferrer">https://www.containerdays.io/containerdays-hamburg-2026/</a></p>',29)]))}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
